package com.rezoxnemesis.videostudio;
import android.app.*;
import android.text.InputType;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.function.Consumer;

/** Manual parameter/pose controls for precisely the same add_solid operation exposed to MCP. */
final class SketchSolidDialog {
    private final Activity activity;private final Consumer<JSONObject> create;private JSONObject program;private final int originalFrames,originalFps;
    private final LinkedHashMap<String,EditText> fields=new LinkedHashMap<>();private TextView status;
    static void show(Activity a,JSONObject document,Consumer<JSONObject> create)throws Exception{new SketchSolidDialog(a,document,create).show();}
    private SketchSolidDialog(Activity a,JSONObject document,Consumer<JSONObject> create)throws Exception{activity=a;this.create=create;originalFrames=document.getInt("frameCount");originalFps=document.getInt("fps");program=SketchSolidPrograms.turn(document.getInt("frameCount"));fields.put("Animation frames",input("Animation frames",document.getInt("frameCount")));fields.put("Animation FPS",input("Animation FPS",document.getInt("fps")));}
    private void show()throws Exception {
        LinearLayout form=column();status=new TextView(activity);status.setText("Shared corners keep faces joined during rotation. Creates a new editable layer. Animation frames and FPS affect this whole sketch; changing duration preserves absolute pose frames.");form.addView(status);
        for(Map.Entry<String,EditText> entry:fields.entrySet())labelled(form,entry.getKey(),entry.getValue());
        Spinner shape=new Spinner(activity);shape.setContentDescription("Solid shape");shape.setAdapter(new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,SketchSolidMesh.SHAPES));labelled(form,"Solid shape",shape);
        String[] dimensions={"Solid width","Solid height","Solid depth"};for(int n=0;n<3;n++)add(form,dimensions[n],program.getJSONArray("size").getDouble(n));
        for(String camera:new String[]{"focal","distance","height","horizon"})add(form,"Camera "+camera,program.getJSONObject("camera").getDouble(camera));add(form,"Outline pixels",program.getDouble("strokePx"));add(form,"Rolling radius (0 disables)",0);
        CheckBox ground=new CheckBox(activity);ground.setText("Floor guides and contact shadow");ground.setChecked(true);form.addView(ground);
        CheckBox volume=new CheckBox(activity);volume.setText("Preserve squash volume");volume.setContentDescription("Preserve squash volume");form.addView(volume);CheckBox world=new CheckBox(activity);world.setText("Squash in world axes");world.setContentDescription("Squash in world axes");form.addView(world);
        CheckBox contact=new CheckBox(activity);contact.setText("Keep on floor (no flight)");contact.setContentDescription("Keep on floor");form.addView(contact);CheckBox soft=new CheckBox(activity);soft.setText("Soft contact shadow");soft.setContentDescription("Soft contact shadow");form.addView(soft);
        CheckBox light=new CheckBox(activity);light.setText("World lighting (smooth curves / shaded faces)");light.setContentDescription("World lighting");form.addView(light);
        CheckBox rock=new CheckBox(activity);rock.setText("Rock about box/pyramid feet");rock.setContentDescription("Rocking pivot");form.addView(rock);CheckBox hold=new CheckBox(activity);hold.setText("Hold final pose to end of sketch");hold.setContentDescription("Hold final pose");form.addView(hold);CheckBox merge=new CheckBox(activity);merge.setText("Share cels during identical held poses");merge.setContentDescription("Merge held cels");form.addView(merge);
        Button poses=new Button(activity);poses.setText("Pose keys");form.addView(poses);poses.setOnClickListener(v->poseList());
        Button study=new Button(activity);study.setText("Load motion study");form.addView(study);study.setOnClickListener(v->{try{program=SketchSolidPrograms.study(SketchSolidMesh.SHAPES.get(shape.getSelectedItemPosition()),Integer.parseInt(fields.get("Animation frames").getText().toString()));volume.setChecked(program.optBoolean("preserveVolume"));world.setChecked("world".equals(program.optString("scaleSpace")));ground.setChecked(program.optBoolean("ground"));contact.setChecked(program.optBoolean("groundLock"));soft.setChecked(program.optBoolean("softShadow"));light.setChecked(program.optBoolean("lighting"));rock.setChecked(program.optBoolean("rockingPivot"));hold.setChecked(program.optBoolean("holdLast"));merge.setChecked(program.optBoolean("mergeHolds"));for(int n=0;n<3;n++)fields.get(dimensions[n]).setText(String.valueOf(program.getJSONArray("size").getDouble(n)));for(String name:new String[]{"focal","distance","height","horizon"})fields.get("Camera "+name).setText(String.valueOf(program.getJSONObject("camera").getDouble(name)));fields.get("Outline pixels").setText(String.valueOf(program.optDouble("strokePx",3)));fields.get("Rolling radius (0 disables)").setText(String.valueOf(program.optDouble("rollingRadius",0)));status.setText("Original "+shape.getSelectedItem()+" motion loaded. Geometry and pose settings replaced; sketch timing preserved.");}catch(Exception e){error(e);}});
        ScrollView scroll=new ScrollView(activity);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("Solid construction").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Construct editable cels",null).create();dialog.show();dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{
            int frames=Integer.parseInt(fields.get("Animation frames").getText().toString()),fps=Integer.parseInt(fields.get("Animation FPS").getText().toString());if(frames<1||frames>1200)throw SketchDocument.bad("Use 1..1200 frames per shot");NativeFrameClock.requireFps(fps);
            program.put("shape",SketchSolidMesh.SHAPES.get(shape.getSelectedItemPosition()));double rolling=value("Rolling radius (0 disables)");if(rolling==0)program.remove("rollingRadius");else program.put("rollingRadius",rolling);JSONArray size=new JSONArray();for(String name:dimensions)size.put(value(name));program.put("size",size).put("strokePx",value("Outline pixels")).put("ground",ground.isChecked()).put("rockingPivot",rock.isChecked()).put("holdLast",hold.isChecked()).put("mergeHolds",merge.isChecked()).put("lighting",light.isChecked()).put("groundLock",contact.isChecked()).put("softShadow",soft.isChecked()).put("preserveVolume",volume.isChecked()).put("scaleSpace",world.isChecked()?"world":"local");JSONObject camera=new JSONObject();for(String name:new String[]{"focal","distance","height","horizon"})camera.put(name,value("Camera "+name));program.put("camera",camera);
            String id="solid_"+UUID.randomUUID().toString().replace("-","");JSONArray operations=new JSONArray();if(frames!=originalFrames||fps!=originalFps)operations.put(new JSONObject().put("type","set_timing").put("frameCount",frames).put("fps",fps));operations.put(new JSONObject().put("type","add_layer").put("layer",new JSONObject().put("id",id).put("name","Solid construction"))).put(new JSONObject().put("type","add_solid").put("layerId",id).put("solidId",id).put("program",SketchDocument.copy(program)));
            new SketchSolidOps.Model(new JSONObject().put("frameCount",frames),program);create.accept(new JSONObject().put("operations",operations));dialog.dismiss();
        }catch(Exception e){error(e);}});
    }
    private void poseList(){try{JSONArray keys=program.getJSONArray("keys");String[] labels=new String[keys.length()+1];for(int n=0;n<keys.length();n++)labels[n]="Pose "+(n+1)+" · frame "+(keys.getJSONObject(n).getInt("frame")+1);labels[keys.length()]="Add pose";new AlertDialog.Builder(activity).setTitle("Solid pose keys").setItems(labels,(d,index)->{try{JSONObject key=index<keys.length()?SketchDocument.copy(keys.getJSONObject(index)):new JSONObject().put("frame",Math.min(1199,keys.getJSONObject(keys.length()-1).getInt("frame")+1)).put("x",0).put("elevation",0).put("depth",0);poseEditor(key,index);}catch(Exception e){error(e);}}).show();}catch(Exception e){error(e);}}
    private void poseEditor(JSONObject key,int index)throws Exception {
        LinearLayout form=column();LinkedHashMap<String,EditText> inputs=new LinkedHashMap<>();EditText frame=input("Pose frame",key.getInt("frame")+1);labelled(form,"Frame (1 based)",frame);
        for(String name:new String[]{"x","elevation","depth","pitch","yaw","roll","scaleX","scaleY","scaleZ","flightHeight"}){EditText value=input("Pose "+name,key.optDouble(name,name.startsWith("scale")?1:0));inputs.put(name,value);labelled(form,poseLabel(name),value);}
        String[] modes={"linear","hold","smooth","ease_in","ease_out","ease_in_out"};Spinner interpolation=new Spinner(activity),vertical=new Spinner(activity),depth=new Spinner(activity),scale=new Spinner(activity);scale.setContentDescription("Scale timing");interpolation.setContentDescription("Pose timing");vertical.setContentDescription("Elevation timing");depth.setContentDescription("Depth timing");for(Spinner spinner:new Spinner[]{interpolation,vertical,depth,scale})spinner.setAdapter(new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,modes));interpolation.setSelection(Math.max(0,Arrays.asList(modes).indexOf(key.optString("interpolation","linear"))));vertical.setSelection(Math.max(0,Arrays.asList(modes).indexOf(key.optString("elevationInterpolation",key.optString("interpolation","linear")))));depth.setSelection(Math.max(0,Arrays.asList(modes).indexOf(key.optString("depthInterpolation",key.optString("interpolation","linear")))));scale.setSelection(Math.max(0,Arrays.asList(modes).indexOf(key.optString("scaleInterpolation",key.optString("interpolation","linear")))));labelled(form,"Scale timing",scale);labelled(form,"Depth timing",depth);labelled(form,"Pose timing",interpolation);labelled(form,"Elevation timing",vertical);
        ScrollView scroll=new ScrollView(activity);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("Edit solid pose").setView(scroll).setNegativeButton("Cancel",null).setNeutralButton("Remove pose",(d,w)->{try{JSONArray next=new JSONArray();for(int n=0;n<program.getJSONArray("keys").length();n++)if(n!=index)next.put(program.getJSONArray("keys").getJSONObject(n));if(next.length()==0)throw SketchDocument.bad("Keep at least one pose");program.put("keys",next);}catch(Exception e){error(e);}}).setPositiveButton("Save pose",null).create();dialog.show();dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{
            JSONObject replacement=new JSONObject().put("frame",Integer.parseInt(frame.getText().toString())-1);for(Map.Entry<String,EditText> entry:inputs.entrySet())replacement.put(entry.getKey(),Double.parseDouble(entry.getValue().getText().toString()));replacement.put("interpolation",modes[interpolation.getSelectedItemPosition()]).put("elevationInterpolation",modes[vertical.getSelectedItemPosition()]).put("depthInterpolation",modes[depth.getSelectedItemPosition()]).put("scaleInterpolation",modes[scale.getSelectedItemPosition()]);
            ArrayList<JSONObject> keys=new ArrayList<>();for(int n=0;n<program.getJSONArray("keys").length();n++)if(n!=index)keys.add(program.getJSONArray("keys").getJSONObject(n));keys.add(replacement);keys.sort(Comparator.comparingInt(k->k.optInt("frame")));program.put("keys",new JSONArray(keys));dialog.dismiss();status.setText(keys.size()+" authored pose keys. Rotation values are unwrapped degrees; elevation is above the ground plane.");
        }catch(Exception e){error(e);}});
    }
    private String poseLabel(String name){switch(name){case "x":return "Horizontal position";case "elevation":return "Clearance at key";case "depth":return "Distance into scene";case "flightHeight":return "Flight arc height to next pose";case "scaleX":return "Width scale";case "scaleY":return "Height scale";case "scaleZ":return "Depth scale";default:return name+" (degrees)";}}
    private LinearLayout column(){LinearLayout form=new LinearLayout(activity);form.setOrientation(1);form.setPadding(16,8,16,8);return form;}
    private void labelled(LinearLayout form,String name,android.view.View field){TextView label=new TextView(activity);label.setText(name);form.addView(label);form.addView(field);}
    private EditText input(String name,double value){EditText f=new EditText(activity);f.setContentDescription(name);f.setHint(name);f.setText(String.valueOf(value));f.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);return f;}
    private EditText input(String name,int value){EditText f=input(name,(double)value);f.setText(String.valueOf(value));return f;}
    private void add(LinearLayout form,String name,double value){EditText input=input(name,value);fields.put(name,input);TextView label=new TextView(activity);label.setText(name);form.addView(label);form.addView(input);}
    private double value(String name){return Double.parseDouble(fields.get(name).getText().toString());}
    private void error(Exception e){Toast.makeText(activity,e.getMessage(),Toast.LENGTH_LONG).show();}
}
